/**
 * Annotation helpers that run inside the engine worker (and the Node test helper).
 * Every mutation here must run inside the caller's journal operation (ctx.mutate).
 * Appearance streams are always regenerated by MuPDF through `annot.update()`;
 * page content is only changed by MuPDF's own `bake()`.
 */
import * as mupdf from 'mupdf';
import type { Quad, Rect } from '../../../shared/engine-api';
import type {
  AnnotCreateSpec,
  AnnotPatch,
  AnnotStyle,
  AnnotSummary,
  FillSignKind,
  Point,
  RGB,
} from './types';
import { FILL_SIGN_KINDS } from './types';

export const FILL_SIGN_KEY = 'GarnetFillSign';
export const FLAG_HIDDEN = 2;
export const FLAG_PRINT = 4;
export const FLAG_NO_ZOOM = 8;
export const FLAG_NO_ROTATE = 16;
export const FLAG_NO_VIEW = 32;
export const FLAG_LOCKED = 128;
const MARKUP = new Set(['Highlight', 'Underline', 'StrikeOut', 'Squiggly']);
const FIXED_SIZE = new Set(['Text', 'FileAttachment', 'Sound']);
type Matrix = [number, number, number, number, number, number];

export function safe<T>(fn: () => T, fallback: T): T {
  try {
    return fn();
  } catch {
    return fallback;
  }
}

export function toRGB(color: readonly number[] | null | undefined): RGB | null {
  if (!color || color.length === 0) return null;
  if (color.length === 1) return [color[0], color[0], color[0]];
  if (color.length === 3) return [color[0], color[1], color[2]];
  if (color.length === 4) {
    const [c, m, y, k] = color;
    return [(1 - c) * (1 - k), (1 - m) * (1 - k), (1 - y) * (1 - k)];
  }
  return null;
}

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));
const finite = (value: number) => Number.isFinite(value);
function checkPoint(p: Point): Point {
  if (!Array.isArray(p) || p.length !== 2 || !finite(p[0]) || !finite(p[1]))
    throw new Error('Invalid point.');
  return [p[0], p[1]];
}
export function normRect(r: Rect): Rect {
  if (!Array.isArray(r) || r.length !== 4 || r.some((v) => !finite(v)))
    throw new Error('Invalid rectangle.');
  return [Math.min(r[0], r[2]), Math.min(r[1], r[3]), Math.max(r[0], r[2]), Math.max(r[1], r[3])];
}
function checkColor(color: RGB | null | undefined): number[] {
  if (!color) return [];
  if (color.length !== 3 || color.some((v) => !finite(v))) throw new Error('Invalid colour.');
  return color.map((v) => clamp(v, 0, 1));
}

export function transformPoint(m: Matrix, p: Point): Point {
  return [m[0] * p[0] + m[2] * p[1] + m[4], m[1] * p[0] + m[3] * p[1] + m[5]];
}
export function transformRect(m: Matrix, r: Rect): Rect {
  const pts = [
    transformPoint(m, [r[0], r[1]]),
    transformPoint(m, [r[2], r[1]]),
    transformPoint(m, [r[0], r[3]]),
    transformPoint(m, [r[2], r[3]]),
  ];
  return [
    Math.min(...pts.map((p) => p[0])),
    Math.min(...pts.map((p) => p[1])),
    Math.max(...pts.map((p) => p[0])),
    Math.max(...pts.map((p) => p[1])),
  ];
}

function dateOf(read: () => Date): number | undefined {
  const value = safe(() => read().getTime(), Number.NaN);
  return Number.isFinite(value) && value > 0 ? value : undefined;
}

/** Unique /NM value; getRandomValues works in every worker context (randomUUID needs a secure one). */
export function uniqueName(): string {
  const bytes = new Uint8Array(12);
  crypto.getRandomValues(bytes);
  return `garnet-${Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('')}`;
}

export function annotId(annot: mupdf.PDFAnnotation): number {
  return annot.getObject().asIndirect();
}

export function fillSignKind(obj: mupdf.PDFObject): FillSignKind | undefined {
  const value = obj.get(FILL_SIGN_KEY);
  if (!value.isName()) return undefined;
  const name = value.asName() as FillSignKind;
  return FILL_SIGN_KINDS.includes(name) ? name : undefined;
}

export function summarize(
  annot: mupdf.PDFAnnotation,
  pageId: number,
  pageIndex: number,
): AnnotSummary {
  const obj = annot.getObject();
  const type = annot.getType();
  const flags = safe(() => annot.getFlags(), 0);
  const summary: AnnotSummary = {
    id: obj.asIndirect(),
    pageId,
    pageIndex,
    type,
    bounds: annot.getBounds(),
    contents: safe(() => annot.getContents(), ''),
    author: safe(() => (annot.hasAuthor() ? annot.getAuthor() : ''), ''),
    subject: safe(() => (annot.hasSubject() ? annot.getSubject() : ''), ''),
    created: dateOf(() => annot.getCreationDate()),
    modified: dateOf(() => annot.getModificationDate()),
    color: toRGB(safe(() => annot.getColor(), [])),
    interiorColor: safe(
      () => (annot.hasInteriorColor() ? toRGB(annot.getInteriorColor()) : null),
      null,
    ),
    opacity: safe(() => annot.getOpacity(), 1),
    hidden: (flags & (FLAG_HIDDEN | FLAG_NO_VIEW)) !== 0,
    locked: (flags & FLAG_LOCKED) !== 0,
  };
  if (safe(() => annot.hasRect(), false)) summary.rect = annot.getRect();
  if (safe(() => annot.hasBorder(), false)) {
    summary.borderWidth = safe(() => annot.getBorderWidth(), 1);
    summary.borderStyle = safe(() => annot.getBorderStyle(), 'Solid');
    const dashes = safe(() => annot.getBorderDashPattern() as number[], []);
    if (dashes.length) summary.dashes = dashes;
  }
  if (safe(() => annot.hasBorderEffect(), false))
    summary.borderEffect = safe(() => annot.getBorderEffect(), 'None');
  const intent = obj.get('IT');
  if (intent.isName()) summary.intent = intent.asName();
  if (safe(() => annot.hasIcon(), false)) summary.icon = safe(() => annot.getIcon(), '');
  if (safe(() => annot.hasQuadPoints(), false)) summary.quads = annot.getQuadPoints();
  if (safe(() => annot.hasVertices(), false)) summary.vertices = annot.getVertices();
  if (safe(() => annot.hasLine(), false)) {
    const line = annot.getLine();
    summary.line = [line[0], line[1]];
  }
  if (safe(() => annot.hasLineEndingStyles(), false))
    summary.lineEndings = annot.getLineEndingStyles();
  if (safe(() => annot.hasInkList(), false)) summary.ink = annot.getInkList();
  // A callout needs a CL entry; files made with MuPDF may carry a stray one on plain text boxes.
  if (safe(() => annot.hasCallout(), false) && obj.get('CL').isArray() && summary.intent !== 'FreeTextTypeWriter') {
    const line = safe(() => annot.getCalloutLine(), null);
    if (line && line.length) summary.callout = line;
  }
  if (type === 'FreeText') {
    const da = safe(() => annot.getDefaultAppearance(), null);
    if (da) {
      summary.font = da.font;
      summary.fontSize = da.size;
      summary.textColor = toRGB(da.color);
    }
    summary.align = safe(() => annot.getQuadding(), 0);
  }
  const irt = obj.get('IRT');
  if (irt.isIndirect()) summary.irt = irt.asIndirect();
  const kind = fillSignKind(obj);
  if (kind) summary.fillSign = kind;
  if (safe(() => annot.hasOpen(), false)) summary.isOpen = safe(() => annot.getIsOpen(), false);
  return summary;
}

export function findAnnot(page: mupdf.PDFPage, id: number): mupdf.PDFAnnotation {
  const annot = page.getAnnotations().find((a) => annotId(a) === id);
  if (!annot) throw new Error('This comment is no longer on the page.');
  return annot;
}

function applyStyle(annot: mupdf.PDFAnnotation, style: AnnotStyle) {
  const type = annot.getType();
  if (style.color !== undefined) annot.setColor(checkColor(style.color) as mupdf.AnnotColor);
  if (style.interiorColor !== undefined && safe(() => annot.hasInteriorColor(), false))
    annot.setInteriorColor(checkColor(style.interiorColor) as mupdf.AnnotColor);
  if (style.opacity !== undefined) {
    if (!finite(style.opacity)) throw new Error('Invalid opacity.');
    annot.setOpacity(clamp(style.opacity, 0.05, 1));
  }
  if (safe(() => annot.hasBorder(), false)) {
    if (style.borderWidth !== undefined) {
      if (!finite(style.borderWidth)) throw new Error('Invalid border width.');
      annot.setBorderWidth(clamp(style.borderWidth, 0, 48));
    }
    if (style.borderStyle !== undefined) {
      annot.setBorderStyle(style.borderStyle);
      if (style.borderStyle === 'Dashed') {
        const dashes =
          style.dashes && style.dashes.length
            ? style.dashes
            : [3 * Math.max(1, annot.getBorderWidth()), 2 * Math.max(1, annot.getBorderWidth())];
        annot.setBorderDashPattern(dashes.map((d) => clamp(d, 0.5, 100)));
      } else annot.clearBorderDash();
    }
  }
  if (style.borderEffect !== undefined && safe(() => annot.hasBorderEffect(), false)) {
    annot.setBorderEffect(style.borderEffect);
    if (style.borderEffect === 'Cloudy') annot.setBorderEffectIntensity(1);
  }
  if (style.lineEndings && type === 'FreeText') annot.setCalloutStyle(style.lineEndings.end);
  else if (style.lineEndings && safe(() => annot.hasLineEndingStyles(), false))
    annot.setLineEndingStyles(style.lineEndings.start, style.lineEndings.end);
  if (style.icon !== undefined && safe(() => annot.hasIcon(), false)) annot.setIcon(style.icon);
  if (type === 'FreeText' && (style.fontSize !== undefined || style.textColor !== undefined)) {
    const da = safe(() => annot.getDefaultAppearance(), {
      font: 'Helv',
      size: 12,
      color: [0, 0, 0] as mupdf.AnnotColor,
    });
    const size = style.fontSize ?? da.size;
    if (!finite(size)) throw new Error('Invalid font size.');
    annot.setDefaultAppearance(
      da.font || 'Helv',
      clamp(size || 12, 4, 144),
      (style.textColor ? checkColor(style.textColor) : da.color) as mupdf.AnnotColor,
    );
  }
  if (style.align !== undefined && type === 'FreeText') annot.setQuadding(style.align);
}

function stampMeta(annot: mupdf.PDFAnnotation, pdf: mupdf.PDFDocument, spec: AnnotCreateSpec) {
  if (spec.fillSign) annot.getObject().put(FILL_SIGN_KEY, pdf.newName(spec.fillSign));
  annot.getObject().put('NM', pdf.newString(uniqueName()));
}

export function createAnnot(
  pdf: mupdf.PDFDocument,
  page: mupdf.PDFPage,
  spec: AnnotCreateSpec,
): mupdf.PDFAnnotation {
  const annot = page.createAnnotation(spec.type);
  try {
    switch (spec.type) {
      case 'Highlight':
      case 'Underline':
      case 'StrikeOut':
      case 'Squiggly':
        if (!spec.quads?.length) throw new Error('Select some text first.');
        annot.setQuadPoints(spec.quads.map(checkQuad));
        break;
      case 'Text': {
        if (!spec.rect) throw new Error('A note needs a position.');
        const r = normRect(spec.rect);
        annot.setRect([r[0], r[1], r[0] + 20, r[1] + 20]);
        annot.setIcon(spec.icon || 'Comment');
        break;
      }
      case 'FreeText':
        if (!spec.rect) throw new Error('A text box needs a rectangle.');
        annot.setDefaultAppearance(
          'Helv',
          clamp(spec.fontSize ?? 12, 4, 144),
          checkColor(spec.textColor ?? [0, 0, 0]) as mupdf.AnnotColor,
        );
        annot.setRect(normRect(spec.rect));
        if (spec.intent) annot.setIntent(spec.intent as mupdf.PDFAnnotationIntent);
        if (spec.callout?.length) annot.setCalloutLine(spec.callout.map(checkPoint));
        // MuPDF gives every new FreeText a default callout line; a plain text box has none.
        else annot.getObject().delete('CL');
        if (spec.callout?.length && !spec.lineEndings) annot.setCalloutStyle('OpenArrow');
        break;
      case 'Square':
      case 'Circle':
        if (!spec.rect) throw new Error('A shape needs a rectangle.');
        annot.setRect(normRect(spec.rect));
        break;
      case 'Line':
        if (!spec.line) throw new Error('A line needs two points.');
        annot.setLine(checkPoint(spec.line[0]), checkPoint(spec.line[1]));
        if (spec.intent) annot.setIntent(spec.intent as mupdf.PDFAnnotationIntent);
        break;
      case 'PolyLine':
      case 'Polygon':
        if (!spec.vertices || spec.vertices.length < 2) throw new Error('Add at least two points.');
        annot.setVertices(spec.vertices.map(checkPoint));
        if (spec.intent) annot.setIntent(spec.intent as mupdf.PDFAnnotationIntent);
        break;
      case 'Ink':
        if (!spec.ink?.length || spec.ink.every((s) => s.length < 2))
          throw new Error('Draw a stroke first.');
        annot.setInkList(spec.ink.filter((s) => s.length).map((s) => s.map(checkPoint)));
        break;
      case 'Stamp':
        if (!spec.rect) throw new Error('A stamp needs a rectangle.');
        annot.setRect(normRect(spec.rect));
        if (spec.image) {
          const image = new mupdf.Image(spec.image);
          try {
            annot.setStampImage(image);
          } finally {
            image.destroy();
          }
          annot.setIntent('StampImage');
        } else annot.setIcon(spec.icon || 'Draft');
        break;
      default:
        throw new Error('This comment type is not supported.');
    }
    applyStyle(annot, { ...spec, icon: undefined });
    if (spec.contents !== undefined) annot.setContents(spec.contents);
    if (spec.author && safe(() => annot.hasAuthor(), false)) annot.setAuthor(spec.author);
    if (spec.subject && safe(() => annot.hasSubject(), false)) annot.setSubject(spec.subject);
    const now = new Date();
    annot.setCreationDate(now);
    annot.setModificationDate(now);
    stampMeta(annot, pdf, spec);
    annot.update();
    return annot;
  } catch (error) {
    page.deleteAnnotation(annot);
    throw error;
  }
}

function checkQuad(q: Quad): Quad {
  if (!Array.isArray(q) || q.length !== 8 || q.some((v) => !finite(v)))
    throw new Error('Invalid text area.');
  return [...q] as Quad;
}

export function patchAnnot(annot: mupdf.PDFAnnotation, patch: AnnotPatch) {
  applyStyle(annot, patch);
  if (patch.rect && safe(() => annot.hasRect(), false)) annot.setRect(normRect(patch.rect));
  if (patch.contents !== undefined) annot.setContents(String(patch.contents));
  if (patch.author !== undefined && safe(() => annot.hasAuthor(), false))
    annot.setAuthor(patch.author);
  if (patch.subject !== undefined && safe(() => annot.hasSubject(), false))
    annot.setSubject(patch.subject);
  if (patch.isOpen !== undefined && safe(() => annot.hasOpen(), false))
    annot.setIsOpen(patch.isOpen);
  annot.setModificationDate(new Date());
  annot.update();
}

/** Applies a page-space affine transform to the annotation geometry and regenerates its appearance. */
export function transformAnnot(annot: mupdf.PDFAnnotation, m: Matrix) {
  if (m.length !== 6 || m.some((v) => !finite(v))) throw new Error('Invalid transform.');
  const T = (p: Point) => transformPoint(m, p);
  const type = annot.getType();
  if (safe(() => annot.hasQuadPoints(), false)) {
    annot.setQuadPoints(
      annot.getQuadPoints().map(
        (q) =>
          [
            ...T([q[0], q[1]]),
            ...T([q[2], q[3]]),
            ...T([q[4], q[5]]),
            ...T([q[6], q[7]]),
          ] as Quad,
      ),
    );
  } else if (safe(() => annot.hasInkList(), false)) {
    annot.setInkList(annot.getInkList().map((stroke) => stroke.map((p) => T(p))));
  } else if (safe(() => annot.hasVertices(), false)) {
    annot.setVertices(annot.getVertices().map((p) => T(p)));
  } else if (safe(() => annot.hasLine(), false)) {
    const [a, b] = annot.getLine();
    annot.setLine(T(a), T(b));
  } else if (safe(() => annot.hasRect(), false)) {
    const r = annot.getRect();
    if (FIXED_SIZE.has(type)) {
      const [x, y] = T([r[0], r[1]]);
      annot.setRect([x, y, x + (r[2] - r[0]), y + (r[3] - r[1])]);
    } else {
      const callout = safe(() => (annot.hasCallout() ? annot.getCalloutLine() : null), null);
      annot.setRect(transformRect(m, r));
      if (callout && callout.length) annot.setCalloutLine(callout.map((p) => T(p)));
    }
  } else throw new Error('This comment cannot be moved.');
  annot.setModificationDate(new Date());
  annot.update();
}

export function isMarkup(type: string) {
  return MARKUP.has(type);
}

export function addReply(
  pdf: mupdf.PDFDocument,
  page: mupdf.PDFPage,
  parent: mupdf.PDFAnnotation,
  contents: string,
  author: string,
): mupdf.PDFAnnotation {
  const reply = page.createAnnotation('Text');
  const b = parent.getBounds();
  reply.setRect([b[0], b[1], b[0] + 20, b[1] + 20]);
  reply.setIcon('Comment');
  reply.setContents(contents);
  if (author) reply.setAuthor(author);
  const obj = reply.getObject();
  obj.put('IRT', pdf.newIndirect(annotId(parent)));
  obj.put('RT', pdf.newName('R'));
  // A reply is shown in its parent's thread, never drawn on the page or printed.
  reply.setFlags(FLAG_NO_VIEW | FLAG_NO_ZOOM | FLAG_NO_ROTATE);
  const now = new Date();
  reply.setCreationDate(now);
  reply.setModificationDate(now);
  obj.put('NM', pdf.newString(uniqueName()));
  reply.update();
  return reply;
}

/** Deletes annotations and every reply below them on the page. Returns the deleted ids. */
export function deleteAnnots(page: mupdf.PDFPage, ids: Iterable<number>): number[] {
  const targets = new Set(ids);
  const annots = [...page.getAnnotations()];
  let grew = true;
  while (grew) {
    grew = false;
    for (const annot of annots) {
      const id = annotId(annot);
      const irt = annot.getObject().get('IRT');
      if (!targets.has(id) && irt.isIndirect() && targets.has(irt.asIndirect())) {
        targets.add(id);
        grew = true;
      }
    }
  }
  const deleted: number[] = [];
  for (const annot of annots) {
    const id = annotId(annot);
    if (targets.has(id)) {
      page.deleteAnnotation(annot);
      deleted.push(id);
    }
  }
  return deleted;
}

/**
 * Flattens (bakes) only the annotations accepted by `select`, using MuPDF's own bake.
 * Other annotations are lifted off their pages for the duration of the bake and restored.
 * Replies and popups of baked annotations are removed first: a NoView reply would otherwise be
 * drawn into the page by bake. Returns the number of annotations baked.
 */
export function bakeAnnotations(
  pdf: mupdf.PDFDocument,
  select: (annot: mupdf.PDFObject, subtype: string, id: number) => boolean,
): number {
  const lifted: { page: mupdf.PDFObject; refs: mupdf.PDFObject[] }[] = [];
  let baked = 0;
  for (let i = 0; i < pdf.countPages(); i++) {
    const page = pdf.findPage(i);
    const annots = page.get('Annots');
    if (!annots.isArray() || annots.length === 0) continue;
    // Keys are object numbers (what IRT / Parent point at); direct dictionaries get unique negatives.
    const entries: { ref: mupdf.PDFObject; key: number; subtype: string }[] = [];
    for (let k = 0; k < annots.length; k++) {
      const ref = annots.get(k);
      const subtypeObject = ref.get('Subtype');
      const subtype = subtypeObject.isName() ? subtypeObject.asName() : '';
      entries.push({ ref, key: ref.isIndirect() ? ref.asIndirect() : -(k + 1), subtype });
    }
    const chosen = new Set<number>();
    for (const entry of entries)
      if (
        entry.subtype !== 'Widget' &&
        entry.subtype !== 'Popup' &&
        select(entry.ref, entry.subtype, entry.key)
      )
        chosen.add(entry.key);
    // Replies to chosen annotations, and their popups, go away with them.
    const dropped = new Set<number>();
    const ofChosen = (o: mupdf.PDFObject) =>
      o.isIndirect() && (chosen.has(o.asIndirect()) || dropped.has(o.asIndirect()));
    let grew = true;
    while (grew) {
      grew = false;
      for (const entry of entries) {
        if (dropped.has(entry.key)) continue;
        const reply = ofChosen(entry.ref.get('IRT'));
        const popup = entry.subtype === 'Popup' && ofChosen(entry.ref.get('Parent'));
        if (reply || popup) {
          dropped.add(entry.key);
          chosen.delete(entry.key);
          grew = true;
        }
      }
    }
    const keep = pdf.newArray();
    const refs: mupdf.PDFObject[] = [];
    for (const entry of entries) {
      if (dropped.has(entry.key)) continue;
      if (entry.subtype === 'Widget' || chosen.has(entry.key)) keep.push(entry.ref);
      else refs.push(entry.ref);
    }
    baked += chosen.size;
    for (const entry of entries) if (chosen.has(entry.key)) entry.ref.delete('Popup');
    page.put('Annots', keep);
    if (refs.length) lifted.push({ page, refs });
  }
  if (baked) pdf.bake(true, false);
  for (const { page, refs } of lifted) {
    let annots = page.get('Annots');
    if (!annots.isArray()) {
      page.put('Annots', pdf.newArray());
      annots = page.get('Annots');
    }
    for (const ref of refs) annots.push(ref);
  }
  return baked;
}

export function isFillSign(dict: mupdf.PDFObject): boolean {
  return fillSignKind(dict) !== undefined;
}

export function isVisibleAnnot(dict: mupdf.PDFObject): boolean {
  const flags = dict.get('F');
  const value = flags.isNumber() ? flags.asNumber() : 0;
  return (value & (FLAG_HIDDEN | FLAG_NO_VIEW)) === 0 && !dict.get('IRT').isIndirect();
}
